package com.clavis.reader;
import android.content.*;import android.widget.*;import java.util.*;
/** Topic choices stay local and apply to both publishers and individual stories. */
final class FeedTopics {
 static final LinkedHashMap<String,String> WORDS=new LinkedHashMap<>();
 static{WORDS.put("Medical","health|medicin|clinical|patient|disease|cancer|hospital|surgery|vaccine|diabet|cardio|mental health|psychiatr|public health|स्वास्थ्य|चिकित्सा|रोग|अस्पताल|मधुमेह|हृदय|कैंसर|टीका");WORDS.put("Technology","software|computer|digital|artificial intelligence|cyber|android|linux|internet|technology|machine learning|तकनीक|प्रौद्योगिकी|कंप्यूटर");WORDS.put("Science","science|scientist|research|discovery|experiment|विज्ञान|वैज्ञानिक|अनुसंधान");WORDS.put("Environment","climate|environment|warming|ecolog|biodiversity|conservation|pollution|renewable|sustainab|पर्यावरण|जलवायु|प्रदूषण");WORDS.put("Business","business|econom|finance|market|trade|investment|inflation");WORDS.put("Politics","politic|election|government|parliament|congress|democra|policy");WORDS.put("India","india|indian|delhi|mumbai|bengaluru|chennai");WORDS.put("World","international|global|world|diploma");WORDS.put("Culture","culture|art |artists|literature|music|cinema|history|museum");WORDS.put("Education","education|school|teaching|student|learning|university");WORDS.put("Social sciences","sociolog|psycholog|society|inequality|humanities|social");WORDS.put("Engineering","engineering|robot|manufactur|materials|infrastructure");WORDS.put("Mathematics","mathematic|statistics|algorithm|geometry");WORDS.put("Physics","physics|quantum|particle|relativity");WORDS.put("Chemistry","chemistry|chemical|molecule|catalys");WORDS.put("Biology","biology|genom|genetic|organism|microb|plant|protein");WORDS.put("Space","space|astronom|planet|galaxy|cosmos|nasa|telescope");}
 static android.content.SharedPreferences prefs(Context c){return c.getSharedPreferences("feed_topics",0);}
 static Set<String> selected(Context c,String kind){return new HashSet<>(prefs(c).getStringSet(kind,Collections.emptySet()));}
 static boolean item(Context c,FeedStore.Feed feed,FeedStore.Item item){return item(selected(c,feed.kind),feed,item);}
 static boolean item(Set<String> topics,FeedStore.Feed feed,FeedStore.Item item){if(topics.isEmpty()||feed.kind.equals("Podcasts"))return true;String text=(item.title+" "+item.description).toLowerCase(Locale.ROOT);for(String topic:topics)if(feed.tags.contains(topic)||matches(text,WORDS.get(topic)))return true;return false;}
 static boolean matches(String text,String terms){if(terms==null)return false;for(String term:terms.split("\\|"))if(text.contains(term))return true;return false;}
 static boolean source(Context c,FeedStore.Feed feed){Set<String> topics=selected(c,feed.kind);if(topics.isEmpty()||feed.kind.equals("Podcasts"))return true;for(String tag:feed.tags)if(topics.contains(tag))return true;for(FeedStore.Item item:feed.items)if(item(topics,feed,item))return true;return false;}
 static ArrayList<FeedStore.Feed> sources(Context c,List<FeedStore.Feed> feeds){ArrayList<FeedStore.Feed> filtered=new ArrayList<>();for(FeedStore.Feed feed:feeds)if(source(c,feed))filtered.add(feed);return filtered;}
 static boolean latest(Context c,String kind){return prefs(c).getBoolean("latest_"+kind,false);}
 static void controls(MainActivity a,LinearLayout panel,String kind,boolean sources){if(kind.equals("Podcasts"))return;LinearLayout row=a.row();Set<String> chosen=selected(a,kind);String label=chosen.isEmpty()?"Topics · All":"Topics · "+String.join(", ",new TreeSet<>(chosen));TextView button=a.button(label,()->choose(a,kind,sources));button.setTextSize(12);button.setMaxLines(2);row.addView(button,new LinearLayout.LayoutParams(0,-2,1));if(!sources){TextView order=a.button(latest(a,kind)?"Latest first":"Popular first",()->{prefs(a).edit().putBoolean("latest_"+kind,!latest(a,kind)).apply();FeedScreens.show(a,kind,false);});order.setTextSize(12);row.addView(order);}panel.addView(row);}
 static void choose(MainActivity a,String kind,boolean sources){String[] labels=WORDS.keySet().toArray(new String[0]);Set<String> chosen=selected(a,kind);boolean[] checked=new boolean[labels.length];for(int n=0;n<labels.length;n++)checked[n]=chosen.contains(labels[n]);new AppDialog.Builder(a).setTitle("Choose topics").setMultiChoiceItems(labels,checked,(d,n,on)->{if(on)chosen.add(labels[n]);else chosen.remove(labels[n]);}).setPositiveButton("Apply",(d,n)->{prefs(a).edit().putStringSet(kind,chosen).apply();FeedScreens.show(a,kind,sources);}).setNeutralButton("All topics",(d,n)->{prefs(a).edit().remove(kind).apply();FeedScreens.show(a,kind,sources);}).setNegativeButton("Cancel",null).show();}
}
